const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const initial=[{id:1,name:'project-brief.pdf',type:'pdf',label:'PDF document',size:'240 KB',kept:false},{id:2,name:'the-good-idea.docx',type:'doc',label:'Microsoft Word',size:'32 KB',kept:true},{id:3,name:'weekend-landscape.png',type:'img',label:'PNG image',size:'1.8 MB',kept:false},{id:4,name:'assets-final.zip',type:'zip',label:'ZIP archive',size:'8.2 MB',kept:false},{id:5,name:'meeting-notes.docx',type:'doc',label:'Microsoft Word',size:'18 KB',kept:false},{id:6,name:'travel-plans.pdf',type:'pdf',label:'PDF document',size:'124 KB',kept:false}];
let files=structuredClone(initial),previews=[1,3],view='all',selected=1,sequence=7;
const icons={pdf:'PDF',doc:'DOC',img:'IMG',zip:'ZIP'};
const icon=f=>`<span class="file-icon ${f.type}" aria-hidden="true">${icons[f.type]}</span>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function render(){const visible=files.filter(f=>(view!=='kept'||f.kept)&&(view!=='temporary'||!f.kept)&&($('#filter').value==='all'||f.type===$('#filter').value)&&f.name.toLowerCase().includes($('#search').value.toLowerCase()));$('#all-count').textContent=files.length;$('#record-count').textContent=`${visible.length} sample files`;$('#view-title').textContent={all:'A place for right now.',kept:'The ones worth keeping.',temporary:'Just passing through.',folders:'Everything in its place.'}[view];
if(view==='folders'){$('#file-list').innerHTML='<div class="app-folders">'+['pdf','doc','img','zip'].map(t=>`<button class="folder ${t==='doc'?'blue':t==='img'?'coral':''}" data-category="${t}"><span>${icons[t]}</span><b>${files.filter(f=>f.type===t).length} files</b></button>`).join('')+'<p>Choose a folder to see its files.</p></div>';$$('[data-category]').forEach(b=>b.onclick=()=>{view='all';$('#filter').value=b.dataset.category;updateNav();render()})}else{$('#file-list').innerHTML=visible.map(f=>`<div class="file-row ${selected===f.id?'selected':''}" data-file="${f.id}" tabindex="0" role="button" aria-label="Preview ${f.name}">${icon(f)}<div class="file-info"><strong>${f.name}</strong><small>${f.label} · ${f.size}</small></div><button class="keep ${f.kept?'saved':''}" data-keep="${f.id}" aria-label="${f.kept?'Make temporary':'Keep'} ${f.name}">${f.kept?'✓ Kept':'＋ Keep'}</button></div>`).join('')||'<p class="empty">No files here. Try another filter or add a sample.</p>';$$('[data-file]').forEach(row=>{const open=()=>{selected=+row.dataset.file;if(!previews.includes(selected))previews.push(selected);switchTab('preview');render();renderPreviews()};row.onclick=open;row.onkeydown=e=>{if(e.target!==row)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});$$('[data-keep]').forEach(b=>b.onclick=e=>{e.stopPropagation();const f=files.find(f=>f.id===+b.dataset.keep);f.kept=!f.kept;toast(f.kept?'Kept. Excluded from automatic cleanup.':'Moved back to Temporary.');render()})} }
function previewBody(f){if(f.type==='img')return '<div class="sample-image" role="img" aria-label="Illustration of rolling green hills and a warm sun"><span></span></div>';if(f.type==='zip')return '<div class="paper"><h4>Archive contents</h4><p>↳ brand-assets/<br>↳ readme.txt<br>↳ logo.svg</p><small>Illustrative archive preview</small></div>';return `<div class="paper"><small>${f.type==='pdf'?'PROJECT STUDIO / BRIEF':'NOTES / WORK IN PROGRESS'}</small><h4>${f.type==='pdf'?'Room to make things.':'A good idea starts here.'}</h4><p>${f.type==='pdf'?'Launch deadline: 21 November.<br>Approved budget: $2,400.':'A calmer space for the everyday.<br>Keep the useful. Let the rest go.'}</p><div class="rule"></div><div class="rule" style="width:65%"></div></div>`}
function renderPreviews(){const oldPositions=new Map($$('[data-card]').map(c=>[c.dataset.card,c.getBoundingClientRect()]));$('#preview-count').textContent=previews.length;$('#preview-cards').innerHTML=previews.map(id=>{const f=files.find(f=>f.id===id);return `<article class="preview-card" data-card="${id}"><div class="card-bar"><button class="grip" aria-label="Drag or use arrow keys to reorder ${f.name}">⠿</button>${icon(f)}<strong>${f.name}</strong><button data-close="${id}" aria-label="Close ${f.name} preview">×</button></div><div class="card-content">${previewBody(f)}</div></article>`}).join('')||'<p class="empty">Select a file to open a preview.</p>';$$('[data-close]').forEach(b=>b.onclick=()=>{previews=previews.filter(id=>id!==+b.dataset.close);renderPreviews()});if(!reduceMotion.matches)$$('[data-card]').forEach(c=>{const old=oldPositions.get(c.dataset.card),current=c.getBoundingClientRect();if(old)c.animate([{transform:`translate(${old.left-current.left}px,${old.top-current.top}px)`},{transform:'translate(0,0)'}],{duration:280,easing:'cubic-bezier(.2,.7,.2,1)'});});$$('.grip').forEach(handle=>{handle.onkeydown=e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const id=+handle.closest('[data-card]').dataset.card,index=previews.indexOf(id),next=Math.max(0,Math.min(previews.length-1,index+(e.key==='ArrowUp'?-1:1)));[previews[index],previews[next]]=[previews[next],previews[index]];renderPreviews();$(`[data-card="${id}"] .grip`).focus()};handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();const card=handle.closest('[data-card]'),id=+card.dataset.card,startY=e.clientY,startX=e.clientX;let lastY=e.clientY,lastX=e.clientX;handle.setPointerCapture(e.pointerId);card.classList.add('dragging');handle.onpointermove=ev=>{lastY=ev.clientY;lastX=ev.clientX;card.style.transform=`translate(${lastX-startX}px,${lastY-startY}px)`};const end=()=>{const target=$$('.preview-card').filter(c=>c!==card).find(c=>{const r=c.getBoundingClientRect();return lastY>=r.top&&lastY<=r.bottom&&lastX>=r.left&&lastX<=r.right});if(target){const from=previews.indexOf(id),to=previews.indexOf(+target.dataset.card);previews.splice(from,1);previews.splice(to,0,id)}renderPreviews()};handle.onpointerup=end;handle.onpointercancel=()=>renderPreviews()}})}
function updateNav(){$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function switchTab(tab){$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#preview-area').hidden=tab!=='preview';$('#ai-area').hidden=tab!=='ai'}
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;updateNav();render()});$$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#search').oninput=render;$('#filter').onchange=render;$('#theme').onclick=()=>$('.app').classList.toggle('dark');$('#add').onclick=()=>{files.push({id:sequence,name:`new-idea-${sequence++}.docx`,type:'doc',label:'Microsoft Word',size:'24 KB',kept:false});view='all';$('#filter').value='all';$('#search').value='';updateNav();render();toast('Sample file moved into your demo vault.')};$('#reset').onclick=()=>{files=structuredClone(initial);previews=[1,3];selected=1;sequence=7;view='all';$('#search').value='';$('#filter').value='all';updateNav();switchTab('preview');render();renderPreviews();toast('Sample vault reset.')};
$$('[data-answer]').forEach(b=>b.onclick=()=>{$('#answer').textContent=b.dataset.answer==='deadline'?'The project launch is due on 21 November. Source: project-brief.pdf.':'The approved project budget is $2,400. Source: project-brief.pdf.';$('#answer').animate([{opacity:0,transform:'translateY(4px)'},{opacity:1,transform:'translateY(0)'}],{duration:reduceMotion.matches?0:250})});
$$('[data-folder]').forEach(b=>b.onclick=()=>{$$('[data-folder]').forEach(x=>x.classList.toggle('selected',x===b));const details={pdf:['project-brief.pdf','PDF document · 240 KB'],doc:['the-good-idea.docx','Microsoft Word · 32 KB'],img:['weekend-landscape.png','PNG image · 1.8 MB']}[b.dataset.folder];$('#folder-detail').innerHTML=`↳ ${details[0]} <span>${details[1]}</span>`;$('#folder-detail').animate([{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:reduceMotion.matches?0:300})});
$('#keep-button').onclick=()=>{const kept=$('#keep-button').getAttribute('aria-pressed')!=='true';$('#keep-button').setAttribute('aria-pressed',kept);$('#keep-button').textContent=kept?'✓ Kept':'♡ Keep';$('#keep-status').textContent=kept?'Kept · protected from cleanup':'Temporary · just added';$('#keep-note').textContent=kept?'This one stays. Automatic cleanup will leave it alone.':'A small decision. One less thing to remember.'};
function cleanup(){const enabled=$('#auto-toggle').getAttribute('aria-checked')==='true',day=+$('#days').value,recycled=enabled&&day>=14;$('#day-label').textContent=`Day ${day}`;$('#temp-example').classList.toggle('recycled',recycled);$('#temp-status').textContent=recycled?'Moved to the Windows Recycle Bin':'Temporary · in your vault';$('#cleanup-message').textContent=!enabled?'Cleanup is off. Nothing is recycled automatically.':recycled?'Old download recycled. Your kept file is still safe.':`${14-day} more days until this temporary file is recycled.`}
$('#auto-toggle').onclick=()=>{$('#auto-toggle').setAttribute('aria-checked',$('#auto-toggle').getAttribute('aria-checked')!=='true');cleanup()};$('#days').oninput=cleanup;render();renderPreviews();
